from functools import lru_cache
import time

# Slow recursive function without cache:
def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

# With cache:
@lru_cache(maxsize=128)
def fib_cached(n):
    if n <= 1:
        return n
    return fib_cached(n - 1) + fib_cached(n - 2)

# Time comparison:
start = time.perf_counter()
print(fib_cached(100))  # 354224848179261915075 (instant!)
print(f"Cached: {time.perf_counter() - start:.6f}s")

# lru_cache on non-recursive function:
@lru_cache(maxsize=None)
def expensive_query(db, user_id):
    print(f"  Fetching user {user_id}...")
    return {"id": user_id, "name": f"User{user_id}"}

print(expensive_query("main", 1))  # Fetches
print(expensive_query("main", 1))  # Cache hit! No "Fetching" message

# Clear cache:
print(fib_cached.cache_info())  # CacheInfo(hits=98, misses=101, maxsize=128, currsize=101)
fib_cached.cache_clear()

