from functools import cache

@cache
def compute(x):
    """Simple unbounded cache (maxsize=None)."""
    return x ** x

# maxsize=None means unlimited cache:
@lru_cache(maxsize=None)
def heavy_func(x):
    return sum(i ** 2 for i in range(x))

