from functools import singledispatch

@singledispatch
def format_value(value):
    """Default handler."""
    return str(value)

@format_value.register(int)
def _(value):
    return f"int: {value:,}"  # With thousands separator

@format_value.register(float)
def _(value):
    return f"float: {value:.2f}"

@format_value.register(str)
def _(value):
    return f"str: '{value}'"

@format_value.register(list)
def _(value):
    items = ", ".join(format_value(v) for v in value)
    return f"list: [{items}]"

@format_value.register(dict)
def _(value):
    items = ", ".join(f"{k}={v}" for k, v in value.items())
    return f"dict: {{{items}}}"

print(format_value(1234567))      # int: 1,234,567
print(format_value(3.14159))      # float: 3.14
print(format_value("hello"))      # str: 'hello'
print(format_value([1, "a", 3.5]))  # list: ...
print(format_value({"a": 1}))    # dict: {a=1}
print(format_value(True))         # True (default handler)

# Register using type hints (Python 3.7+):
@format_value.register
def _(value: set):
    return f"set({len(value)} items)"

# Check dispatch:
print(format_value.dispatch(int))  # <function _ at ...>

# All registered types:
print(format_value.registry.keys())  # dict_keys([int, float, ...])

# Stack type-specific and general:
@format_value.register(tuple)
def _(value):
    return format_value(list(value))  # Reuse list handler

from functools import wraps

# Bad decorator — loses metadata:
def bad_logger(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@bad_logger
def add(a, b):
    """Add two numbers."""
    return a + b

print(add.__name__)  # 'wrapper' (wrong!)
print(add.__doc__)   # None (lost!)

# Good decorator — preserves metadata:
def good_logger(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@good_logger
def subtract(a, b):
    """Subtract b from a."""
    return a - b

print(subtract.__name__)  # 'subtract' (preserved!)
print(subtract.__doc__)   # 'Subtract b from a.' (preserved!)

# @wraps copies: __name__, __doc__, __module__, __qualname__, __dict__, __wrapped__
print(subtract.__wrapped__)  # <function subtract at 0x...>

# Always use @wraps in your decorators!
def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        import time
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} took {elapsed:.4f}s")
        return result
    return wrapper

@timer
def slow_func():
    import time
    time.sleep(0.1)
    return "done"

print(slow_func())  # slow_func took 0.1001s
print(slow_func.__name__)  # slow_func (preserved!)

from collections import UserDict, UserList, UserString

# UserDict — dict subclass with custom behavior:
class CaseInsensitiveDict(UserDict):
    def __setitem__(self, key, value):
        super().__setitem__(key.lower(), value)

    def __getitem__(self, key):
        return super().__getitem__(key.lower())

    def __contains__(self, key):
        return super().__contains__(key.lower())

d = CaseInsensitiveDict()
d["Name"] = "Alice"
print(d["name"])     # Alice (lowercase access works!)
print(d["NAME"])     # Alice
print(d.data)         # {'name': 'Alice'}

# UserList — list subclass with custom behavior:
class UniqueList(UserList):
    def __init__(self, initlist=None):
        super().__init__()
        if initlist:
            for item in initlist:
                if item not in self.data:
                    self.data.append(item)

    def append(self, item):
        if item not in self.data:
            super().append(item)

    def extend(self, other):
        for item in other:
            if item not in self.data:
                self.data.append(item)

ul = UniqueList([1, 2, 2, 3, 3, 1])
print(ul)  # [1, 2, 3]
ul.append(2)
ul.append(4)
print(ul)  # [1, 2, 3, 4]

# UserString — string subclass:
class UpperString(UserString):
    def __init__(self, seq):
        super().__init__(str(seq).upper())

    def append(self, char):
        self.data += char.upper()

us = UpperString("hello")
print(us)        # HELLO
us.append("X")
print(us)        # HELLOX

# UserDict is preferred over inheriting from dict directly
# because it wraps the built-in dict in a separate data attribute,
# avoiding issues with C-level methods
